#!/usr/bin/env python
import argparse
from argparse import RawTextHelpFormatter
from ta_emss.utilities.SCFC_parser_lib.scfc_elements.Managed_Object import ManagedObject
from ta_emss.utilities.SCFC_parser_lib.file_managers.SCFC_reader import ScfcReader
from ta_emss.utilities.SCFC_parser_lib.file_managers.YAML_writer import YamlWriter
from ta_emss.utilities.SCFC_parser_lib.file_managers.JSON_writer import JsonWriter
from ta_emss.utilities.SCFC_parser_lib.interfaces.SCFC_value_translator import ScfcValueTranslator


class ScfcParserMain(argparse.ArgumentParser):
    def __init__(self):
        super(ScfcParserMain, self).__init__(description="SCFC converter", formatter_class=RawTextHelpFormatter)
        self.add_argument('scfc', help='Required argument, SCFC file to convert (input file)')
        self.add_argument('--no_yaml', dest='yaml', action='store_false', help='turns off yaml file creation')
        self.add_argument('--no_json', dest='json', action='store_false', help='turns off json file creation')
        self.add_argument('--emss_host', default="10.0.1.1", help='EMSS host - needed for SCFC values translation\ndefault: 10.0.1.1')
        self.add_argument('--emss_port', default=4001, type=int, help='EMSS JSON-RPC port (ute_emss) - needed for SCFC values translation')
        self.add_argument('--yaml_file', help='YAML output file, by default file is created in input file\'s directory')
        self.add_argument('--json_file', help='JSON output file, by default file is created in input file\'s directory')
        self.add_argument('--replace', nargs='*', help='replace ids of managed objects in YAML file using specified rules,\n'
                                                       'rules syntax: <SCFC_MANAGED_OBJECT>=<NAME_OF_ID>\n'
                                                       ' e.g.: LNBTS-88=ENB_ID LNCEL-1=PCELL, CAREL-1=SCELL', default=[])
        self._arguments = None
        self._to_replace = None

    def get_emss_host(self):
        return self._arguments["emss_host"]

    def get_emss_port(self):
        return self._arguments["emss_port"]

    def get_scfc_file_path(self):
        return self._arguments['scfc']

    def get_yaml_file_path(self):
        path = self._arguments['yaml_file']
        if path is None:
            path = self.change_extension_to_yaml(self.get_scfc_file_path())
        return path

    def get_json_file_path(self):
        path = self._arguments['json_file']
        if path is None:
            path = self.change_extension_to_json(self.get_scfc_file_path())
        return path

    def change_extension_to_yaml(self, path):
        return ".".join(path.split(".")[:-1]) + ".yaml"

    def change_extension_to_json(self, path):
        return ".".join(path.split(".")[:-1]) + ".json"

    def handle_input_data(self):
        self._arguments = self.get_arguments()
        self._to_replace = self.parse_to_replace_args_to_dict(self._arguments['replace'])
        self._scfc_file_path = self.get_scfc_file_path()
        self._yaml_file_path = self.get_yaml_file_path()
        self._json_file_path = self.get_json_file_path()

    def get_data_for_yaml(self):
        return self.merge_dicts(*[m_o.get_yaml_object_dict() for m_o in self.managed_objects])

    def get_data_for_json(self):
        return self.merge_dicts(*[m_o.get_emss_object_dict() for m_o in self.managed_objects])

    def merge_dicts(self, *dict_args):
        result = {}
        for dictionary in dict_args:
            result.update(dictionary)
        return result

    def write_data_to_yaml(self, data):
        YamlWriter(data).write_to_file(self._yaml_file_path)

    def write_data_to_json(self, data):
        JsonWriter(data).write_to_file(self._json_file_path)

    def translate_scfc_values(self):
        ScfcValueTranslator(self.get_emss_host(), self.get_emss_port()).translate(self.managed_objects)

    def is_yaml_requested(self):
        return bool(self._arguments["yaml"])

    def is_json_requested(self):
        return bool(self._arguments["json"])

    def write_config_to_files(self):
        if self.is_yaml_requested():
            self.write_data_to_yaml(self.get_data_for_yaml())
        if self.is_json_requested():
            self.write_data_to_json(self.get_data_for_json())

    def run(self):
        self.handle_input_data()
        self.managed_objects = [ManagedObject(m_o, self._to_replace) for m_o in self.get_managed_objects_from_scfc()]
        self.translate_scfc_values()
        self.write_config_to_files()

    def convert(self, host, port, scfc_file, yaml_file=None):
        self.set_args(host, port, scfc_file, yaml_file)
        self.managed_objects = [ManagedObject(m_o, self._to_replace) for m_o in self.get_managed_objects_from_scfc()]
        self.translate_scfc_values()
        self.write_config_to_files()

    def set_args(self, host, port, scfc_file, yaml_file):
        self._arguments = {}
        self._arguments["emss_host"] = host
        self._arguments["emss_port"] = port
        self._arguments["yaml_file"] = yaml_file if yaml_file else None
        self._arguments["scfc"] = scfc_file
        self._arguments["replace"] = []
        self._arguments["json"] = False
        self._arguments["yaml"] = True
        self._arguments["json_file"] = None
        self._scfc_file_path = self.get_scfc_file_path()
        self._yaml_file_path = self.get_yaml_file_path()
        self._json_file_path = self.get_json_file_path()
        self._to_replace = self.parse_to_replace_args_to_dict(self._arguments['replace'])

    def get_managed_objects_from_scfc(self):
        reader = ScfcReader()
        xml_file = reader.open_file(self._scfc_file_path)
        return reader.get_xml_managed_objects(xml_file)

    def get_arguments(self):
        return vars(self.parse_args())

    def parse_to_replace_args_to_dict(self, to_replace):
        return dict([pair.split("=") for pair in to_replace])


if __name__ == "__main__":
    ScfcParserMain().run()
